from collections import deque


def shortest_bridge(grid):
    n, m = len(grid), len(grid[0])
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    visited = [[False] * m for _ in range(n)]

    def in_bounds(r, c):
        return 0 <= r < n and 0 <= c < m

    def dfs(r, c, island_cells):
        if not in_bounds(r, c) or visited[r][c] or grid[r][c] == 0:
            return
        visited[r][c] = True
        island_cells.append((r, c))
        for dr, dc in dirs:
            dfs(r + dr, c + dc, island_cells)

    island1 = []
    found = False
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 1:
                dfs(r, c, island1)
                found = True
                break
        if found:
            break

    queue = deque((r, c, 0) for r, c in island1)
    while queue:
        r, c, d = queue.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if not in_bounds(nr, nc) or visited[nr][nc]:
                continue
            if grid[nr][nc] == 1:
                return d
            visited[nr][nc] = True
            queue.append((nr, nc, d + 1))

    return -1


if __name__ == "__main__":
    print(shortest_bridge([[0, 1], [1, 0]]))
    print(shortest_bridge([[0, 1, 0], [0, 0, 0], [0, 0, 1]]))

