import java.util.*;

public class Main {
    static int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    static boolean[][] visited;
    static int n, m;

    static void dfs(int r, int c, int[][] grid, List<int[]> cells) {
        if (r < 0 || r >= n || c < 0 || c >= m || visited[r][c] || grid[r][c] == 0) return;
        visited[r][c] = true;
        cells.add(new int[]{r, c});
        for (int[] d : dirs) dfs(r + d[0], c + d[1], grid, cells);
    }

    static int shortestBridge(int[][] grid) {
        n = grid.length; m = grid[0].length;
        visited = new boolean[n][m];
        List<int[]> island1 = new ArrayList<>();

        outer:
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 1) {
                    dfs(r, c, grid, island1);
                    break outer;
                }
            }
        }

        Queue<int[]> queue = new LinkedList<>();
        for (int[] cell : island1) queue.add(new int[]{cell[0], cell[1], 0});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0], c = cur[1], d = cur[2];
            for (int[] dir : dirs) {
                int nr = r + dir[0], nc = c + dir[1];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m || visited[nr][nc]) continue;
                if (grid[nr][nc] == 1) return d;
                visited[nr][nc] = true;
                queue.add(new int[]{nr, nc, d + 1});
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        System.out.println(shortestBridge(new int[][]{{0, 1}, {1, 0}}));
        System.out.println(shortestBridge(new int[][]{{0, 1, 0}, {0, 0, 0}, {0, 0, 1}}));
    }
}

