    visited[r][c] = true;
    cells.push_back({r, c});
    for (int i = 0; i < 4; i++) dfs(r + dr4[i], c + dc4[i], grid, cells);
}

int shortestBridge(vector<vector<int>>& grid) {
    n = grid.size(); m = grid[0].size();
    visited.assign(n, vector<bool>(m, false));
    vector<pair<int,int>> island1;

    bool found = false;
    for (int r = 0; r < n && !found; r++) {
        for (int c = 0; c < m && !found; c++) {
            if (grid[r][c] == 1) {
                dfs(r, c, grid, island1);
                found = true;
            }
        }
    }

    queue<tuple<int,int,int>> q;
    for (auto& [r, c] : island1) q.push({r, c, 0});

    while (!q.empty()) {
        auto [r, c, d] = q.front(); q.pop();
        for (int i = 0; i < 4; i++) {
            int nr = r + dr4[i], nc = c + dc4[i];
            if (nr < 0 || nr >= n || nc < 0 || nc >= m || visited[nr][nc]) continue;
            if (grid[nr][nc] == 1) return d;
            visited[nr][nc] = true;
            q.push({nr, nc, d + 1});
        }
    }
    return -1;
}

int main() {
    vector<vector<int>> g1 = {{0, 1}, {1, 0}};
    cout << shortestBridge(g1) << endl;
    vector<vector<int>> g2 = {{0, 1, 0}, {0, 0, 0}, {0, 0, 1}};
    cout << shortestBridge(g2) << endl;
    return 0;
}

